        $receiptArgs=@{Workspace=$importWorkspace;PairId=$importPlan.PairId;PlanPath=$importPlanPath;PlanHash=$importPlanHash;ManifestPath=$importManifestPath;ManifestHash=$importManifestHash;Generation=7;TargetSnapshotHash=$targetInventoryHash;ComparisonRevision=$comparison.Revision;SelectionRevision=$importPlan.Assistive.SourceSelectionsVersion;Decision='RestoreNow';Owner='Fixture target owner';Reason='Review target state after imported NonC readback.';SelectedItemIds=$selectedImportIds;ExpectedDecisionRevision=$comparisonCatalog.DecisionRevision}
        $targetReceipt=Export-WsmAssistiveTargetDecisionReceipt @receiptArgs
        $targetReceiptRecord=Assert-WsmAssistiveTargetDecisionReceipt (Read-WsmTrustedJson $targetReceipt.ReceiptPath $targetReceipt.ReceiptHash)
