        $catalogPath=Get-WsmCatalogPath $importWorkspace $importPlan.PairId;$catalogBytes=[IO.File]::ReadAllBytes($catalogPath);$currentPersisted=Get-WsmCatalog $importWorkspace $importPlan.PairId
        try{$changedApproval=$currentPersisted;$changedApproval.Approval.Hash=('f'*64);$changedApproval.Assistive.ResultReferences=@();Write-WsmJson $catalogPath $changedApproval;$changedPlanImport=$importArgs.Clone();$changedPlanImport.ExpectedRevision=$changedApproval.DecisionRevision;$changedPlanRejected=$false;$changedPlanError='';try{Import-WsmAssistiveNonCResult @changedPlanImport|Out-Null}catch{$changedPlanRejected=$true;$changedPlanError=$_.Exception.Message};Check ($changedPlanRejected -and $changedPlanError -match 'current approved sealed catalog plan') ('Importer did not reject the otherwise-unused transfer at the changed-current-approval guard: '+$changedPlanError)}finally{[IO.File]::WriteAllBytes($catalogPath,$catalogBytes)}
        Check ((Get-WsmCatalog $importWorkspace $importPlan.PairId).Approval.Hash -ieq $importPlanHash) 'Changed-plan negative did not restore the exact current approval.'
        $catalogBytes=[IO.File]::ReadAllBytes($catalogPath);$currentPersisted=Get-WsmCatalog $importWorkspace $importPlan.PairId
