        $restoredCatalog=Get-WsmCatalog $importWorkspace $importPlan.PairId
        Check ($restoredCatalog.DecisionRevision -eq $comparisonCatalog.DecisionRevision -and $restoredCatalog.Approval.Hash -ieq $importPlanHash -and $restoredCatalog.Assistive.Comparison.Revision -eq $comparisonCatalog.Assistive.Comparison.Revision) 'Old-state consumer counterexample did not restore exact current catalog bytes and approval.'
